import { register, tryResolve } from "../../extensions/contracts.js";
import { MISSING_EXTENSION_ERROR } from "../../extensions/errors.js";
import { importFirstPartyExtensionModule, isMissingFirstPartyExtensionModule, } from "../../extensions/first-party-import.js";
import { NodeTelemetryProviderName, } from "../../extensions/observability/index.js";
import { SandboxShellToolsProviderName, } from "../../extensions/sandbox/index.js";
import { getRuntimeAgentSourceContextSchema } from "../runtime/agent-invocation-contract.js";
import { snapshotHostedRuntimeSourceIdentity, } from "./runtime-source-binding.js";
import { snapshotOwnDeploymentArtifactOption } from "../service/deployment-artifact.js";
import { resolveEnvironment, resolveServiceName, } from "./cloud-agent-paths.js";
async function loadDefaultCreateBashTool() {
    const provider = tryResolve(SandboxShellToolsProviderName);
    if (provider)
        return provider;
    try {
        const { createBashSandboxShellToolsProvider } = await importFirstPartyExtensionModule("ext-sandbox-shell-tools", "@veryfront/ext-sandbox-shell-tools");
        return createBashSandboxShellToolsProvider;
    }
    catch (error) {
        throw MISSING_EXTENSION_ERROR.create({
            message: 'Missing extension for contract "SandboxShellToolsProvider". Install @veryfront/ext-sandbox-shell-tools or pass createBashTool explicitly.',
            detail: `Veryfront cloud agent sandbox shell tools require a SandboxShellToolsProvider implementation: ${error instanceof Error ? error.message : String(error)}`,
        });
    }
}
/** Ensures a SchemaValidator is registered, falling back to the built-in Zod adapter. */
export async function ensureDefaultSchemaValidator() {
    if (tryResolve("SchemaValidator"))
        return;
    const { createZodAdapter } = await importFirstPartyExtensionModule("ext-schema-zod", "@veryfront/ext-schema-zod");
    if (tryResolve("SchemaValidator"))
        return;
    const validator = createZodAdapter();
    if (!tryResolve("SchemaValidator")) {
        register("SchemaValidator", validator);
    }
}
async function ensureDefaultAuthProvider() {
    if (tryResolve("AuthProvider"))
        return;
    const { createAuthProvider } = await importFirstPartyExtensionModule("ext-auth-jwt", "@veryfront/ext-auth-jwt");
    register("AuthProvider", createAuthProvider({}));
}
async function ensureDefaultNodeTelemetryProvider() {
    if (tryResolve(NodeTelemetryProviderName))
        return;
    const OpenTelemetryNodeTelemetryProvider = await importOpenTelemetryNodeTelemetryProvider();
    if (!OpenTelemetryNodeTelemetryProvider)
        return;
    register(NodeTelemetryProviderName, new OpenTelemetryNodeTelemetryProvider());
}
async function importOpenTelemetryNodeTelemetryProvider() {
    try {
        const { OpenTelemetryNodeTelemetryProvider } = await importFirstPartyExtensionModule("ext-observability-opentelemetry", "@veryfront/ext-observability-opentelemetry");
        return OpenTelemetryNodeTelemetryProvider;
    }
    catch (error) {
        if (!isMissingOpenTelemetryNodeTelemetryProviderError(error)) {
            throw error;
        }
        return null;
    }
}
/** @internal Classify only absence of the optional OpenTelemetry extension itself. */
export function isMissingOpenTelemetryNodeTelemetryProviderError(error) {
    return isMissingFirstPartyExtensionModule(error, [
        "extensions/ext-observability-opentelemetry/src/index",
        "@veryfront/ext-observability-opentelemetry",
    ]);
}
/** Validates and snapshots an explicit runtime source identity, rejecting branch sources. */
export function resolveHostedRuntimeSourceIdentity(input) {
    if (input === undefined)
        return undefined;
    const source = getRuntimeAgentSourceContextSchema().parse(input);
    if (source.type === "branch") {
        throw new Error("Agent service runtimeSource must identify an immutable release or environment source.");
    }
    return snapshotHostedRuntimeSourceIdentity(source);
}
/**
 * Resolves all agent service options, registering default extensions (schema, auth,
 * telemetry, bash) if not already present. Returns options with `createBashTool`
 * and `serviceName` guaranteed.
 */
export async function resolveNodeVeryfrontCloudAgentServiceOptions(options) {
    const deploymentArtifact = snapshotOwnDeploymentArtifactOption(options);
    const environment = resolveEnvironment(options);
    await ensureDefaultSchemaValidator();
    await ensureDefaultAuthProvider();
    await ensureDefaultNodeTelemetryProvider();
    return {
        serviceName: resolveServiceName({
            serviceName: options.serviceName,
            baseDir: options.baseDir,
            entrypointUrl: options.entrypointUrl,
            projectDir: options.projectDir,
            env: environment,
            processTarget: options.processTarget,
        }),
        agentId: options.agentId,
        baseDir: options.baseDir,
        projectDir: options.projectDir,
        entrypointUrl: options.entrypointUrl,
        runtimeSource: resolveHostedRuntimeSourceIdentity(options.runtimeSource),
        deploymentArtifact,
        agentSource: options.agentSource,
        mcpServers: options.mcpServers,
        forwardedConfigNamespace: options.forwardedConfigNamespace,
        hostToolPolicy: options.hostToolPolicy,
        projectDefinitionBootstrap: options.projectDefinitionBootstrap,
        hostedModelCallCapture: options.hostedModelCallCapture,
        createRemoteToolSource: options.createRemoteToolSource,
        createBashTool: options.createBashTool ?? await loadDefaultCreateBashTool(),
        env: options.env,
        processTarget: options.processTarget,
        drainTimeoutMs: options.drainTimeoutMs,
        hardShutdownTimeoutMs: options.hardShutdownTimeoutMs,
        signals: options.signals,
    };
}
